<?php

declare(strict_types=1);

namespace App\Hosts;

/**
 * The fixed values of host protocol 1 that the Go host holds too.
 * Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.
 */
final readonly class HostProtocol
{
    public const int VERSION = 1;

    /**
     * The names the host itself fills as {host:NAME} in a plan.
     */
    public const array HOST_NAMES = [
        'JOURNAL_URL',
        'INSTALLATION',
        'HOOK_COMMAND',
        'JOURNAL_AGENT',
    ];

    /**
     * The plan fields a contained plan may not name, as it names nothing of the host it runs on.
     */
    public const array CONTAINED_REFUSED_FIELDS = [
        'folders',
        'side_sockets',
        'read_files',
        'inherit',
    ];

    /**
     * What journal-hook takes after its own name, in order.
     */
    public const array HOOK_ARGUMENTS = [
        'driver',
        'reply file',
    ];
}
